// Each row stores its generated attributes under a 'generated.' key prefix.
// Flatten to the column names the demander's back-office CSV expects.
return items.map(item => {
  const src = item.json.generated_fields || {};
  const out = {};
  for (const key in src) {
    if (Object.prototype.hasOwnProperty.call(src, key)) {
      out[key.replace('generated.', '')] = src[key];
    }
  }
  return { json: out };
});
